WITH cleaned AS (SELECT *, TO_DATE(reading_ts) AS reading_ts_date FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 05:00:00'), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts_date DESC, id) AS latest_rank FROM cleaned) ranked WHERE latest_rank = 1), scored AS (SELECT *, MIN(pressure) OVER (PARTITION BY device_code) AS device_code_min_pressure, FIRST_VALUE(pressure, TRUE) OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pressure FROM deduped), with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM scored), with_gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '1' HOUR THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), filtered AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, reading_ts_date, latest_rank, first_known_pressure, prev_reading_ts, is_new_burst, session_id, CAST(humidity AS INT) AS humidity_int FROM sessionized WHERE pressure > 1025), with_windows AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, reading_ts_date, latest_rank, first_known_pressure, prev_reading_ts, is_new_burst, session_id, humidity_int, ROW_NUMBER() OVER (ORDER BY latest_rank, id) AS row_seq, CUME_DIST() OVER (PARTITION BY device_code ORDER BY first_known_pressure DESC) AS first_known_pressure_cume_dist, AVG(humidity_int) OVER (PARTITION BY device_code ORDER BY session_id, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS humidity_int_avg_5 FROM filtered) SELECT *, SUM(status_bits) OVER (PARTITION BY device_code ORDER BY humidity_int, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_bits, SUM(temp_c) OVER (ORDER BY reading_ts_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_temp_c, DENSE_RANK() OVER (PARTITION BY device_code ORDER BY session_id) AS session_id_dense_rank FROM with_windows;
